# Q25 report patch (idempotent): python3 -I build_report_q25.py
import json
p='/output/report.json'; r=json.load(open(p))
r['results']=[x for x in r['results'] if not x['quantity'].startswith('Q25')]
A=lambda n,v:{"name":n,"value":v}
com=[A("data","ALMA archive Band 3 pbcor cubes (image products, no restoration): 2015.1.00993.S Michiyama (spw0 87827 MHz, 12m, beam 2.10x1.67\", 26 km/s channels) and 2015.1.00412.S Harada (spw1 88144 MHz, 12m, beam 1.38x1.14\", 3.3 km/s channels); both lines in each cube (HCN 1-0 at 87.81, HCO+ 1-0 at 88.36 GHz). 2-1 = Xb55 as Q11."),
     A("convention","moment-0 +-350 km/s about 2780 km/s (radio, LSRK), pbcor, Jy km/s, convolved to a 10\" circular beam (same kernel code as Q11), annuli 0-4/4-8/6-9/8-12\" about the N-S midpoint (-0.075,0). PB(88 GHz)~71\" so PB>0.9 inside 12\": no PB masking needed. Tb ratios = Jy ratios x (nu_HCO+/nu_HCN)^2=1.0126 for HCN/HCO+, x(nu10/nu21)^2=0.25 for 2-1/1-0 ladders."),
     A("noise","annulus flux noise = scatter of the same annulus in 4 line-free 700 km/s windows (excluding +-900 km/s about both lines)")]
def add(q,t,v,u,un,c,e): r['results'].append({"quantity":q,"target":t,"value":v,"uncertainty":un,"unit":u,"confidence":c,"evidence":e,"assumptions":com})
add("Q25a: HCN/HCO+ 1-0 disk ratio at 10\" beam, annuli 0-4/4-8/6-9/8-12\": Michiyama (2015.1.00993.S) 0.645/0.619/0.602/0.559, Harada (2015.1.00412.S) 0.648/0.610/0.576/0.447; the two 1-0 datasets disagree on the 8-12\" decline",
 "disk, 8-12\"",
 "Jy-ratio (Tb x1.0126 = 0.654/0.627/0.609/0.566 Michiyama). 8-12\"/4-8\" decline factor: Michiyama 0.902+-0.016 (10% decline), Harada 0.733+-0.03 (27% decline), 2-1 Xb55 0.889 (11%, Q11). 8-12\" HCN/HCO+ fluxes (Jy km/s): Michiyama 6.54/11.69, Harada 2.93/6.55 (Harada recovers 0.45 (HCN), 0.56 (HCO+) of Michiyama in this ring; 12\" cumulative 0.75 / 0.78 of Michiyama, 0.5-0.57 at 20\"). Michiyama's 1-0 ratio decline therefore equals the 2-1 decline (0.90 vs 0.89), Harada's is stronger and is attributable to its poorer recovery of extended emission (its curve of growth falls beyond 12\", bowl). High-pass tests (out/q25/q25_uvtest.log): a cosine high-pass up to 3-4 kl applied to Michiyama or Xb55 keeps the 8-12/4-8 factor at 0.91-0.92 (Michiyama) / 0.86-0.80 (Xb55), i.e. a simple uv cut does NOT reproduce Harada's 0.73; the Harada 8-12\" deficit is thus a deconvolution/uv-sampling property of that image that we cannot model without the visibilities. Literature: Harada+2018 (ApJ 855, 49, Sect. 3.2.1) quote HCN/HCO+ 1-0 ~1.0 (N nucleus) and ~0.6 (S) in Tb at 230 pc (1.2\") beams; no published disk 8-12\" value. Our 0-4\" 0.65 (10\" beam) is the beam-blended nuclear+disk value, consistent with S~0.6.",
 "ratio","stat 0.005-0.02 per annulus; systematic (recovery) dominates 8-12\": Michiyama vs Harada differ by 0.11","medium",
 "scripts/q25_ratio10.py, q25_growth.py, q25_uvtest.py (+q11_likeforlike_lib.py) -> out/q25/q25_ratio10.log, q25_growth.log, q25_uvtest.log, q25_ratio10.json")
add("Q25b: the 1-0 and 2-1 HCN/HCO+ disk ratios are parallel: R21/R10 = 0.896/0.895/0.893/0.88 (Michiyama) from 0-4 to 8-12\"; the 8-12\" decline is the same in 1-0 and 2-1 (answer to Q25)",
 "disk, 8-12\"",
 "Answer: with the better-recovered 1-0 data (Michiyama) the 8-12\" decline of HCN/HCO+ is ~10% in 1-0 (0.902+-0.016) and ~11% in 2-1 (0.889): the same within errors, so it is present in a transition free of the Q11 3-2 systematics (PB, bowl). The 3-2 extra fall of Q11 (eps 0.05-0.45) is therefore not mirrored in 1-0 vs 2-1: R21/R10 is flat (-2% over the disk). Harada alone (0.73) would suggest a larger 1-0 decline, but is a recovery-limited image (see Q25a). Ladder (Tb) per annulus 0-4/4-8/6-9/8-12\": HCN 2-1/1-0 0.567/0.496/0.523/0.436, HCO+ 0.632/0.555/0.586/0.495 (Michiyama); both fall ~22-23% from the nucleus to the 8-12\" annulus, equally for the two species. Harada ladders 0.62/0.61/0.72/0.97 (HCN), 0.69/0.67/0.77/0.88 (HCO+): rising to ~1 at 8-12\" is unphysical for a sub-thermal disk and flags the Harada 1-0 8-12\" flux as incomplete.",
 "ratio","10% cross-band flux scale on ladders; R21/R10 stat +-0.01","medium",
 "scripts/q25_ratio10.py, q25_radex.py -> out/q25/q25_ratio10.log, q25_radex.log")
add("Q25c: RADEX translation of the 1-0/2-1 disk ratios (Michiyama 1-0 + Xb55 2-1, 10\"): no HCN/HCO+ abundance gradient is required; a modest density drop in the outer annulus suffices (low confidence)",
 "disk, 4-8\" and 8-12\"",
 "Chi2 fit of [R10, R21, HCN 2-1/1-0, HCO+ 2-1/1-0] on the LAMDA RADEX grid (Tk 10-150 K, log n 3-8, N 1e13-3e18, dv 150 km/s, Tbg 2.73 K; errors 4% ratios, 14% ladders; scripts/q25_radexfit.py, out/q25/q25_radexfit.log). X=N(HCN)/N(HCO+) is pinned at log X=+0.50 (3.2) in all annuli (0-4, 4-8, 8-12\") for Tk=20-50 K, i.e. delta log X = 0.00 (+-0.25 grid step): no abundance-ratio gradient needed. At Tk=20 K log n 4.75-5.00 (4-8\") -> 4.25-4.75 (8-12\"); Tk=30-50 K log n 3-5.0 -> 3-4.75/4.5: a ~0.25-0.5 dex density decrease is allowed/preferred but not required (degenerate with N, which is poorly bounded: log N(HCO+) 15.5-17.75). Fits at fixed Tk have chi2 3-10 for 0 dof-ish (4 obs, 3 free: logn, NH, NO), i.e. acceptable. Same fit to Harada: 8-12\" demands log n 6.25 and log X<-0.75 (unphysical ladders ~1), rejecting Harada's 8-12\" flux as incomplete. Caveat: single-zone, same dv/beam filling for all lines, no hyperfine HCN, LAMDA collision rates with H2 only.",
 "dex","grid step 0.25 dex; degenerate N-n-Tk","low",
 "scripts/q25_radex.py, q25_radexfit.py -> out/q25/q25_radex.log, q25_radexfit.log, radex_hcn.npy, radex_hco+.npy")
r['datasets'].append({'files':['member.uid___A001_X2fb_X961.ari_l.ngc3256_sci.spw0_87827MHz.12m.cube.I.pbcor.fits','member.uid___A001_X33e_X145.ari_l.NGC_3256_sci.spw1_88144MHz.12m.cube.I.pbcor.fits'],'content':'Band 3 HCN/HCO+ 1-0 pbcor cubes: 2015.1.00993.S (Michiyama, 2.1x1.7") and 2015.1.00412.S (Harada, 1.38x1.14")','role':'Q25 1-0 disk ratio at 10" and 2-1/1-0 ladder per annulus'})
json.dump(r,open(p,'w'),indent=1)
